277	func TestRenderGolden(t *testing.T) {
278		got, err := Render(Defaults())
279		if err != nil {
280			t.Fatalf("Render(Defaults()): %v", err)
281		}
282		if *updateGolden {
283			if err := os.MkdirAll(filepath.Dir(goldenDefault), 0o755); err != nil {
284				t.Fatal(err)
285			}
286			if err := os.WriteFile(goldenDefault, got, 0o644); err != nil {
287				t.Fatal(err)
288			}
289			return
290		}
291		want, err := os.ReadFile(goldenDefault)
292		if err != nil {
293			t.Fatalf("%v\nrun: go test ./internal/nexusbench -run TestRenderGolden -update", err)
294		}
295		if !bytes.Equal(got, want) {
296			t.Errorf("the render of Defaults() differs from %s (run with -update and review the diff)\n--- got ---\n%s\n--- want ---\n%s", goldenDefault, got, want)
297		}
298	}
