344	func TestRenderStream(t *testing.T) {
345		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
346			t.Run(name, func(t *testing.T) {
347				r := mustRender(t, p)
348				if !reflect.DeepEqual(r.kinds, wantKinds) {
349					t.Fatalf("kinds = %v, want %v (Namespace first)", r.kinds, wantKinds)
350				}
351				for i, n := range r.nodes {
352					var o object
353					if err := n.Decode(&o); err != nil {
354						t.Fatal(err)
355					}
356					if o.APIVersion == "" || o.Metadata.Name == "" {
357						t.Errorf("document %d (%s) has no apiVersion or no metadata.name", i, o.Kind)
358					}
359					if o.Kind == "Namespace" {
360						if o.Metadata.Name != p.Namespace {
361							t.Errorf("Namespace name = %q, want %q", o.Metadata.Name, p.Namespace)
362						}
363						if o.Metadata.Namespace != "" {
364							t.Errorf("a Namespace carries metadata.namespace = %q", o.Metadata.Namespace)
365						}
366						continue
367					}
368					if o.Metadata.Namespace != p.Namespace {
369						t.Errorf("%s metadata.namespace = %q, want %q", o.Kind, o.Metadata.Namespace, p.Namespace)
370					}
371				}
372			})
373		}
374	}
