376	func TestRenderNamespaceOnly(t *testing.T) {
377		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
378			t.Run(name, func(t *testing.T) {
379				raw, err := RenderNamespace(p)
380				if err != nil {
381					t.Fatal(err)
382				}
383				only := decodeStream(t, raw)
384				if !reflect.DeepEqual(only.kinds, []string{"Namespace"}) {
385					t.Fatalf("kinds = %v, want only a Namespace", only.kinds)
386				}
387				// The Namespace of RenderNamespace is the one Render starts with.
388				var alone, first any
389				if err := only.nodes[0].Decode(&alone); err != nil {
390					t.Fatal(err)
391				}
392				full := mustRender(t, p)
393				if err := full.nodes[0].Decode(&first); err != nil {
394					t.Fatal(err)
395				}
396				if !reflect.DeepEqual(alone, first) {
397					t.Errorf("RenderNamespace = %v, want the first document of Render = %v", alone, first)
398				}
399				again, err := RenderNamespace(p)
400				if err != nil {
401					t.Fatal(err)
402				}
403				if !bytes.Equal(raw, again) {
404					t.Error("RenderNamespace is not deterministic")
405				}
406			})
407		}
408	}
