498	func TestRenderDeploymentShape(t *testing.T) {
499		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
500			t.Run(name, func(t *testing.T) {
501				r := mustRender(t, p)
502				d := r.deployment(t)
503				spec := d.Spec
504	
505				if spec.Replicas == nil || *spec.Replicas != 1 {
506					t.Errorf("replicas = %v, want 1", spec.Replicas)
507				}
508				if spec.Strategy.Type != "Recreate" {
509					t.Errorf("strategy.type = %q, want Recreate (one ReadWriteOnce volume)", spec.Strategy.Type)
510				}
511				if spec.Strategy.RollingUpdate.Kind != 0 {
512					t.Error("strategy.rollingUpdate is set next to Recreate: Kubernetes refuses it")
513				}
514	
515				if got := spec.Selector.MatchLabels[labelName]; got != "nexus" {
516					t.Errorf("selector %s = %q, want nexus", labelName, got)
517				}
518				podLabels := spec.Template.Metadata.Labels
519				if podLabels[labelName] != "nexus" {
520					t.Errorf("pod label %s = %q, want nexus", labelName, podLabels[labelName])
521				}
522				for k, v := range spec.Selector.MatchLabels {
523					if podLabels[k] != v {
524						t.Errorf("the selector asks %s=%s but the pods carry %q", k, v, podLabels[k])
525					}
526				}
527	
528				pod := spec.Template.Spec
529				if pod.AutomountServiceAccountToken == nil || *pod.AutomountServiceAccountToken {
530					t.Errorf("automountServiceAccountToken = %v, want false", pod.AutomountServiceAccountToken)
531				}
532				if pod.EnableServiceLinks == nil || *pod.EnableServiceLinks {
533					t.Errorf("enableServiceLinks = %v, want false", pod.EnableServiceLinks)
534				}
535				if len(pod.Containers) != 1 {
536					t.Fatalf("%d containers, want 1", len(pod.Containers))
537				}
538	
539				pvc := r.pvc(t)
540				mounted := false
541				for _, c := range pod.Containers {
542					for _, m := range c.VolumeMounts {
543						if m.MountPath != "/nexus-data" {
544							continue
545						}
546						for _, v := range pod.Volumes {
547							if v.Name == m.Name && v.PersistentVolumeClaim != nil && v.PersistentVolumeClaim.ClaimName == pvc.Metadata.Name {
548								mounted = true
549							}
550						}
551					}
552				}
553				if !mounted {
554					t.Errorf("no container mounts the PVC %q on /nexus-data", pvc.Metadata.Name)
555				}
556			})
557		}
558	}
