560	func TestRenderContainersAreHardened(t *testing.T) {
561		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
562			t.Run(name, func(t *testing.T) {
563				d := mustRender(t, p).deployment(t)
564				pod := d.Spec.Template.Spec
565				for _, c := range allContainers(d) {
566					sc := c.SecurityContext
567					if sc == nil {
568						t.Fatalf("container %s has no securityContext", c.Name)
569					}
570					// The pod level and the container level both count: the
571					// container's value wins, as in Kubernetes.
572					user := firstInt64(sc.RunAsUser, podSC(pod).RunAsUser)
573					group := firstInt64(sc.RunAsGroup, podSC(pod).RunAsGroup)
574					nonRoot := firstBool(sc.RunAsNonRoot, podSC(pod).RunAsNonRoot)
575					if user == nil || *user != 200 {
576						t.Errorf("container %s: runAsUser = %v, want 200 (the nexus user of the image)", c.Name, user)
577					}
578					if group == nil || *group != 200 {
579						t.Errorf("container %s: runAsGroup = %v, want 200", c.Name, group)
580					}
581					if nonRoot == nil || !*nonRoot {
582						t.Errorf("container %s: runAsNonRoot = %v, want true", c.Name, nonRoot)
583					}
584					if sc.AllowPrivilegeEscalation == nil || *sc.AllowPrivilegeEscalation {
585						t.Errorf("container %s: allowPrivilegeEscalation = %v, want false", c.Name, sc.AllowPrivilegeEscalation)
586					}
587					if sc.Capabilities == nil || !reflect.DeepEqual(sc.Capabilities.Drop, []string{"ALL"}) || len(sc.Capabilities.Add) != 0 {
588						t.Errorf("container %s: capabilities = %+v, want drop [ALL] and no add", c.Name, sc.Capabilities)
589					}
590					seccomp := sc.SeccompProfile
591					if seccomp == nil {
592						seccomp = podSC(pod).SeccompProfile
593					}
594					if seccomp == nil || seccomp.Type != "RuntimeDefault" {
595						t.Errorf("container %s: seccompProfile = %+v, want RuntimeDefault", c.Name, seccomp)
596					}
597				}
598			})
599		}
