123	// Defaults returns the parameters of the bench as D-B and D-C define them.
124	// Hosts, SecretsPath and DescriptorPath stay empty: the tool derives them.
125	func Defaults() Params {
126		return Params{
127			Context:        defaultContext,
128			Namespace:      defaultNamespace,
129			Image:          defaultImage,
130			ImageTag:       defaultImageTag,
131			HTTPNodePort:   defaultHTTPNodePort,
132			DockerNodePort: defaultDockerNodePort,
133			CPURequest:     "500m",
134			CPULimit:       "2",
135			MemoryRequest:  "3Gi",
136			MemoryLimit:    "4Gi",
137			StorageSize:    "5Gi",
138			JVMOpts:        defaultJVMOpts,
139			UpstreamURL:    upstreamFor(defaultNamespace),
140			Anonymous:      true,
141			Timeout:        10 * time.Minute,
142			DeleteTimeout:  3 * time.Minute,
143		}
