202	// envSetters lists every variable but the namespace, which FromEnv handles
203	// itself because it also moves the upstream URL.
204	var envSetters = []envSetter{
205		stringSetter(envContext, func(p *Params) *string { return &p.Context }),
206		portSetter(envHTTPNodePort, func(p *Params) *int { return &p.HTTPNodePort }),
207		portSetter(envDockerNodePort, func(p *Params) *int { return &p.DockerNodePort }),
208		stringSetter(envCPURequest, func(p *Params) *string { return &p.CPURequest }),
209		stringSetter(envCPULimit, func(p *Params) *string { return &p.CPULimit }),
210		stringSetter(envMemoryRequest, func(p *Params) *string { return &p.MemoryRequest }),
211		stringSetter(envMemoryLimit, func(p *Params) *string { return &p.MemoryLimit }),
212		stringSetter(envStorageSize, func(p *Params) *string { return &p.StorageSize }),
213		stringSetter(envJVMOpts, func(p *Params) *string { return &p.JVMOpts }),
214		stringSetter(envImage, func(p *Params) *string { return &p.Image }),
215		stringSetter(envImageTag, func(p *Params) *string { return &p.ImageTag }),
216		stringSetter(envUpstreamURL, func(p *Params) *string { return &p.UpstreamURL }),
217		boolSetter(envAnonymous, func(p *Params) *bool { return &p.Anonymous }),
218		// Accepting a license is the user's decision: only the exact word "yes" counts.
219		{envAcceptEULA, func(p *Params, v string) error {
220			p.AcceptEULA = v == "yes"
221			return nil
222		}},
223		{envHosts, func(p *Params, v string) error {
224			p.Hosts = splitList(v)
225			return nil
226		}},
227		durationSetter(envTimeout, func(p *Params) *time.Duration { return &p.Timeout }),
228		durationSetter(envDeleteTimeout, func(p *Params) *time.Duration { return &p.DeleteTimeout }),
229		stringSetter(envSecrets, func(p *Params) *string { return &p.SecretsPath }),
230		stringSetter(envDescriptor, func(p *Params) *string { return &p.DescriptorPath }),
231	}
