588						t.Errorf("container %s: capabilities = %+v, want drop [ALL] and no add", c.Name, sc.Capabilities)
589					}
590					seccomp := sc.SeccompProfile
591					if seccomp == nil {
592						seccomp = podSC(pod).SeccompProfile
593					}
594					if seccomp == nil || seccomp.Type != "RuntimeDefault" {
595						t.Errorf("container %s: seccompProfile = %+v, want RuntimeDefault", c.Name, seccomp)
596					}
597				}
598			})
599		}
