678	func TestRenderProbes(t *testing.T) {
679		for name, p := range map[string]Params{"defaults": Defaults(), "custom": customParams()} {
680			t.Run(name, func(t *testing.T) {
681				d := mustRender(t, p).deployment(t)
682				for _, c := range allContainers(d) {
683					if c.LivenessProbe != nil {
684						t.Errorf("container %s has a livenessProbe: a restart in the middle of the first start would loop", c.Name)
685					}
686					for probeName, pr := range map[string]*probe{"startupProbe": c.StartupProbe, "readinessProbe": c.ReadinessProbe} {
687						if pr == nil || pr.HTTPGet == nil {
688							t.Errorf("container %s: %s is missing or is not an httpGet", c.Name, probeName)
689							continue
690						}
691						if pr.HTTPGet.Path != statusPath {
692							t.Errorf("container %s: %s path = %q, want %q", c.Name, probeName, pr.HTTPGet.Path, statusPath)
693						}
694						if port := resolvePort(pr.HTTPGet.Port, c); port != 8081 {
695							t.Errorf("container %s: %s port = %q resolves to %d, want 8081", c.Name, probeName, pr.HTTPGet.Port.Value, port)
696						}
697					}
698					// The start of Nexus takes minutes: the startup probe waits up to 10 minutes.
699					if sp := c.StartupProbe; sp != nil {
700						if budget := sp.PeriodSeconds * sp.FailureThreshold; budget < 600 {
701							t.Errorf("container %s: startupProbe waits %d s (periodSeconds %d x failureThreshold %d), want at least 600", c.Name, budget, sp.PeriodSeconds, sp.FailureThreshold)
702						}
703					}
704				}
705			})
706		}
707	}
