798		nodePorts := map[int]bool{}
799		for _, sp := range svc.Spec.Ports {
800			nodePorts[sp.NodePort] = true
801		}
802		if !nodePorts[30581] || !nodePorts[30582] || len(nodePorts) != 2 {
803			t.Errorf("nodePorts = %v, want 30581 and 30582", nodePorts)
804		}
