807	// TestRenderQuotesEveryValue pins the engagement of docs/architecture/nexus-bench.md:
808	// the template writes each value it renders between double quotes, so the
809	// validation is the first guard and not the only one.
810	func TestRenderQuotesEveryValue(t *testing.T) {
811		p := customParams()
812		text := string(mustRender(t, p).raw)
813	
814		values := []string{
815			p.Namespace, p.ImageRef(), p.JVMOpts,
816			p.CPURequest, p.CPULimit, p.MemoryRequest, p.MemoryLimit, p.StorageSize,
817		}
818		for _, v := range values {
819			occurrences := 0
820			for from := 0; ; {
821				i := strings.Index(text[from:], v)
822				if i < 0 {
823					break
824				}
825				i += from
826				from = i + len(v)
827				occurrences++
828				if i == 0 || text[i-1] != '"' || from >= len(text) || text[from] != '"' {
829					start, end := max(0, i-30), min(len(text), from+30)
830					t.Errorf("the value %q is not written between double quotes: ...%s...", v, text[start:end])
831				}
832			}
833			if occurrences == 0 {
834				t.Errorf("the value %q does not appear in the render", v)
835			}
836		}
837	}
