839	// TestRenderRoundTripsTrickyJVMOpts renders values that Validate accepts and
840	// that a plain YAML scalar would read as a number, a boolean, a null, a float or
841	// a mapping, and checks the value decodes as the same string.
842	func TestRenderRoundTripsTrickyJVMOpts(t *testing.T) {
843		cases := []string{
844			"-Dfoo=a:b",
845			"-Dfoo=a:b -Dbar=c:d",
846			"-Dpath=/a/b+c@d%e,f",
847			"-Xmx1g",
848			"true",
849			"false",
850			"null",
851			"yes",
852			"no",
853			"on",
854			"123",
855			"1.5",
856			"1e3",
857			"0x1F",
858			"0o17",
859			"12:30:45",
860			"1,000",
861			"-1",
862			"-.inf",
863			"-.nan",
864			"2001-01-23",
865			"a b",
866		}
867		for _, opts := range cases {
868			t.Run(opts, func(t *testing.T) {
869				p := Defaults()
870				p.JVMOpts = opts
871				if err := p.Validate(); err != nil {
872					t.Fatalf("the case is meant to be valid but Validate refuses %q: %v", opts, err)
873				}
874				d := mustRender(t, p).deployment(t)
875				found := false
876				for _, c := range allContainers(d) {
877					for _, e := range c.Env {
878						if e.Name != "INSTALL4J_ADD_VM_PARAMS" {
879							continue
880						}
881						found = true
882						if e.Value.Tag != "!!str" {
883							t.Errorf("the value decodes as %s, want !!str", e.Value.Tag)
884						}
885						if e.Value.Value != opts {
886							t.Errorf("decoded value = %q, want %q", e.Value.Value, opts)
887						}
888					}
889				}
890				if !found {
891					t.Error("INSTALL4J_ADD_VM_PARAMS is not set")
892				}
893			})
894		}
895	}
