66	var (
67		// dns1123Label is a Kubernetes namespace name; the length is checked apart.
68		dns1123Label = regexp.MustCompile(`^[a-z0-9]([-a-z0-9]*[a-z0-9])?$`)
69		// contextName is kept to characters that are safe in a file name and in a
70		// kubectl argument: the context names a directory of the secrets path.
71		contextName = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._@-]*$`)
72		// cpuQuantity is a Kubernetes CPU quantity: whole or decimal cores, or milli-cores.
73		cpuQuantity = regexp.MustCompile(`^([0-9]+(\.[0-9]+)?|[0-9]+m)$`)
74		// byteQuantity is a Kubernetes quantity of bytes: a number and an optional
75		// binary (Ki..Ei) or decimal (k, M, G, T, P, E) suffix. Exponent forms are not accepted.
76		byteQuantity = regexp.MustCompile(`^([0-9]+(?:\.[0-9]+)?)(Ki|Mi|Gi|Ti|Pi|Ei|k|M|G|T|P|E)?$`)
77		// jvmOptsChars rules out quotes, backslashes, braces, '#', '&', '*', '!',
78		// '|', '>' and every control character (newlines included), so a value
79		// cannot end a YAML scalar or start another node.
80		jvmOptsChars = regexp.MustCompile(`^[A-Za-z0-9 _.,:=/+@%-]+$`)
81		// jvmOptsStart keeps the first character from being a YAML indicator: a
82		// letter, a digit, or '-' followed by a non-space (so not "- x", a sequence entry).
83		jvmOptsStart = regexp.MustCompile(`^([A-Za-z0-9]|-[^ ])`)
84		imageChars   = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._/:-]*$`)
85		imageTag     = regexp.MustCompile(`^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$`)
86		hostName     = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
87		urlChars     = regexp.MustCompile(`^[A-Za-z0-9._~:/%-]+$`)
88	)
