116		// Hosts are the addresses the NodePorts are tried on; nil means the tool
117		// works them out (127.0.0.1 and the node's InternalIP).
118		Hosts                       []string
119		Timeout, DeleteTimeout      time.Duration
120		SecretsPath, DescriptorPath string
121	}
