156	// envSetter applies the value of one non-empty variable to p.
157	type envSetter struct {
158		name  string
159		apply func(p *Params, value string) error
160	}
161	
162	func stringSetter(name string, field func(p *Params) *string) envSetter {
163		return envSetter{name, func(p *Params, v string) error {
164			*field(p) = v
165			return nil
166		}}
167	}
168	
169	func portSetter(name string, field func(p *Params) *int) envSetter {
170		return envSetter{name, func(p *Params, v string) error {
171			n, err := strconv.Atoi(v)
172			if err != nil {
173				return fmt.Errorf("%s: %q is not a whole number", name, v)
174			}
175			*field(p) = n
176			return nil
177		}}
178	}
179	
180	func durationSetter(name string, field func(p *Params) *time.Duration) envSetter {
181		return envSetter{name, func(p *Params, v string) error {
182			d, err := time.ParseDuration(v)
183			if err != nil {
184				return fmt.Errorf("%s: %q is not a duration such as 90s or 10m", name, v)
185			}
186			*field(p) = d
187			return nil
188		}}
189	}
190	
191	func boolSetter(name string, field func(p *Params) *bool) envSetter {
192		return envSetter{name, func(p *Params, v string) error {
193			b, err := strconv.ParseBool(v)
194			if err != nil {
195				return fmt.Errorf("%s: %q is not true or false", name, v)
196			}
197			*field(p) = b
198			return nil
199		}}
200	}
